    AENV tp TSD CTX TH sb SO T rest mE -> mem_inv asegs mE ->
    AFR mE j8 -> stk asegs mE lo (bv_unsigned sp + -128) ->
    rw_cells asegs mE (a + 6128) [C1 ob0; C1 (b8 hb1); C2 (wz 0); C4 (wz size); C8 (wz id)] ->
    0 <= hb1 < 256 -> b1_ok (Z.land hb1 243) ->
